const BYTES_STORED: u32 = 3;
const MONO_FLAG: u32 = 4;
const HYBRID_FLAG: u32 = 8;
const JOINT_STEREO: u32 = 0x10;
const FLOAT_DATA: u32 = 0x80;
const INT32_DATA: u32 = 0x100;
const HYBRID_BITRATE: u32 = 0x200;
const HYBRID_BALANCE: u32 = 0x400;
const INITIAL_BLOCK: u32 = 0x800;
const FINAL_BLOCK: u32 = 0x1000;
const SHIFT_LSB: u32 = 13;
const SHIFT_MASK: u32 = 0x1f << SHIFT_LSB;
const MAG_LSB: u32 = 18;
const MAG_MASK: u32 = 0x1f << MAG_LSB;
const SRATE_LSB: u32 = 23;
const SRATE_MASK: u32 = 0xf << SRATE_LSB;
const FALSE_STEREO: u32 = 0x4000_0000;
const DSD_FLAG: u32 = 0x8000_0000;
const MONO_DATA: u32 = MONO_FLAG | FALSE_STEREO;

const ID_DECORR_TERMS: u8 = 0x2;
const ID_DECORR_WEIGHTS: u8 = 0x3;
const ID_DECORR_SAMPLES: u8 = 0x4;
const ID_ENTROPY_VARS: u8 = 0x5;
const ID_HYBRID_PROFILE: u8 = 0x6;
const ID_FLOAT_INFO: u8 = 0x8;
const ID_INT32_INFO: u8 = 0x9;
const ID_WV_BITSTREAM: u8 = 0xa;
const ID_WVX_BITSTREAM: u8 = 0xc;
const ID_CHANNEL_INFO: u8 = 0xd;
const ID_DSD_BLOCK: u8 = 0xe;
const ID_SAMPLE_RATE: u8 = 0x27;
const ID_WVX_NEW_BITSTREAM: u8 = 0x2c;

const MAX_TERM: usize = 8;
const SLS: u32 = 8;
const SLO: u32 = 1 << (SLS - 1);
const LIMIT_ONES: u32 = 16;
const DIV: [u32; 3] = [128, 64, 32];

const RATES: [u32; 15] = [
    6000, 8000, 9600, 11025, 12000, 16000, 22050, 24000, 32000, 44100, 48000, 64000, 88200, 96000,
    192_000,
];

pub fn sniff(data: &[u8]) -> bool {
    data.len() >= 32 && &data[..4] == b"wvpk"
}

fn bad(msg: &str) -> Error {
    Error::corrupt(msg.to_string())
}

// ---- logarithms (the format stores levels as 8.8 fixed-point log2) ----

fn nbits(x: u32) -> u32 {
    32 - x.leading_zeros()
}

fn wp_log2(avalue: u32) -> i32 {
    let a = avalue.wrapping_add(avalue >> 9);
    if a < 256 {
        let d = nbits(a);
        ((d << 8) + u32::from(LOG2[((a << (9 - d)) & 0xff) as usize])) as i32
    } else {
        let d = if a < 1 << 16 {
            nbits(a >> 8) + 8
        } else if a < 1 << 24 {
            nbits(a >> 16) + 16
        } else {
            nbits(a >> 24) + 24
        };
        ((d << 8) + u32::from(LOG2[((a >> (d - 9)) & 0xff) as usize])) as i32
    }
}

fn wp_exp2s(log: i32) -> i32 {
    if log < 0 {
        return !((wp_exp2s(log.wrapping_neg()) as u32).wrapping_sub(1)) as i32;
    }
    let value = u32::from(EXP2[(log & 0xff) as usize]) | 0x100;
    let l = log >> 8;
    if l <= 9 {
        (value >> (9 - l)) as i32
    } else {
        (value << ((l - 9) & 0x1f)) as i32
    }
}

fn restore_weight(w: i8) -> i32 {
    let mut r = i32::from(w) * 8;
    if r > 0 {
        r += (r + 64) >> 7;
    }
    r
}

// ---- bit reader (least significant bit first) ----

struct Bits<'a> {
    data: &'a [u8],
    pos: usize,
    eof: bool,
}

impl<'a> Bits<'a> {
    fn new(data: &'a [u8]) -> Self {
        Self {
            data,
            pos: 0,
            eof: false,
        }
    }
    fn bit(&mut self) -> u32 {
        match self.data.get(self.pos >> 3) {
            Some(&b) => {
                let v = (b >> (self.pos & 7)) & 1;
                self.pos += 1;
                u32::from(v)
            }
            None => {
                self.eof = true;
                0
            }
        }
    }
    fn bits(&mut self, n: u32) -> u32 {
        let mut v = 0u32;
        for i in 0..n {
            v |= self.bit() << i;
        }
        v
    }
    /// A value 0..=`maxcode`, in the minimum number of bits (truncated binary).
    fn code(&mut self, maxcode: u32) -> u32 {
        if maxcode < 2 {
            return if maxcode != 0 { self.bit() } else { 0 };
        }
        let bitcount = nbits(maxcode);
        let extras = (1u32 << bitcount) - maxcode - 1;
        let low = self.bits(bitcount - 1);
        if low >= extras {
            (low << 1) - extras + self.bit()
        } else {
            low
        }
    }
    /// An Elias-gamma-like count used for long runs.
    fn escape(&mut self) -> Option<u32> {
        let mut cbits = 0u32;
        while cbits < 33 && self.bit() != 0 {
            cbits += 1;
        }
        if cbits == 33 {
            return None;
        }
        if cbits < 2 {
            return Some(cbits);
        }
        let mut v = 0u32;
        let mut mask = 1u32;
        cbits -= 1;
        while cbits > 0 {
            if self.bit() != 0 {
                v |= mask;
            }
            mask <<= 1;
            cbits -= 1;
        }
        Some(v | mask)
    }
}

// ---- entropy decoding ----

#[derive(Default, Clone, Copy)]
struct Chan {
    median: [u32; 3],
    slow_level: u32,
    error_limit: u32,
}

#[derive(Default)]
struct Words {
    c: [Chan; 2],
    bitrate_delta: [u32; 2],
    bitrate_acc: [u32; 2],
    holding_one: bool,
    holding_zero: bool,
    zeros_acc: u32,
}

fn get_med(c: &Chan, i: usize) -> u32 {
    (c.median[i] >> 4) + 1
}
fn inc_med(c: &mut Chan, i: usize) {
    let d = DIV[i];
    c.median[i] = c.median[i].wrapping_add(((c.median[i] + d) / d) * 5);
}
fn dec_med(c: &mut Chan, i: usize) {
    let d = DIV[i];
    c.median[i] = c.median[i].wrapping_sub(((c.median[i] + (d - 2)) / d) * 2);
}

impl Words {
    fn update_error_limit(&mut self, flags: u32) {
        self.bitrate_acc[0] = self.bitrate_acc[0].wrapping_add(self.bitrate_delta[0]);
        let mut bitrate0 = (self.bitrate_acc[0] >> 16) as i32;
        let level = |c: &Chan| (c.slow_level.wrapping_add(SLO) >> SLS) as i32;
        let limit = |slow: i32, rate: i32| -> u32 {
            if slow - rate > -0x100 {
                wp_exp2s(slow - rate + 0x100) as u32
            } else {
                0
            }
        };
        if flags & MONO_DATA != 0 {
            self.c[0].error_limit = if flags & HYBRID_BITRATE != 0 {
                limit(level(&self.c[0]), bitrate0)
            } else {
                wp_exp2s(bitrate0) as u32
            };
            return;
        }
        self.bitrate_acc[1] = self.bitrate_acc[1].wrapping_add(self.bitrate_delta[1]);
        let mut bitrate1 = (self.bitrate_acc[1] >> 16) as i32;
        if flags & HYBRID_BITRATE != 0 {
            let s0 = level(&self.c[0]);
            let s1 = level(&self.c[1]);
            if flags & HYBRID_BALANCE != 0 {
                let balance = (s1 - s0 + bitrate1 + 1) >> 1;
                if balance > bitrate0 {
                    bitrate1 = bitrate0 * 2;
                    bitrate0 = 0;
                } else if -balance > bitrate0 {
                    bitrate0 *= 2;
                    bitrate1 = 0;
                } else {
                    bitrate1 = bitrate0 + balance;
                    bitrate0 -= balance;
                }
            }
            self.c[0].error_limit = limit(s0, bitrate0);
            self.c[1].error_limit = limit(s1, bitrate1);
        } else {
            self.c[0].error_limit = wp_exp2s(bitrate0) as u32;
            self.c[1].error_limit = wp_exp2s(bitrate1) as u32;
        }
    }

    /// The next residual of channel `chan`, or `None` when the bitstream is exhausted.
    fn get_word(&mut self, bs: &mut Bits, chan: usize, flags: u32) -> Option<i32> {
        if self.c[0].median[0] & !1 == 0
            && !self.holding_zero
            && !self.holding_one
            && self.c[1].median[0] & !1 == 0
        {
            if self.zeros_acc != 0 {
                self.zeros_acc -= 1;
                if self.zeros_acc != 0 {
                    let c = &mut self.c[chan];
                    c.slow_level = c
                        .slow_level
                        .wrapping_sub(c.slow_level.wrapping_add(SLO) >> SLS);
                    return Some(0);
                }
            } else {
                self.zeros_acc = bs.escape()?;
                if self.zeros_acc != 0 {
                    let c = &mut self.c[chan];
                    c.slow_level = c
                        .slow_level
                        .wrapping_sub(c.slow_level.wrapping_add(SLO) >> SLS);
                    self.c[0].median = [0; 3];
                    self.c[1].median = [0; 3];
                    return Some(0);
                }
            }
        }
        let mut ones;
        if self.holding_zero {
            self.holding_zero = false;
            ones = 0;
        } else {
            ones = 0;
            while ones < LIMIT_ONES + 1 && bs.bit() != 0 {
                ones += 1;
            }
            if ones >= LIMIT_ONES {
                if ones == LIMIT_ONES + 1 {
                    return None;
                }
                ones = bs.escape()? + LIMIT_ONES;
            }
            if self.holding_one {
                self.holding_one = ones & 1 != 0;
                ones = (ones >> 1) + 1;
            } else {
                self.holding_one = ones & 1 != 0;
                ones >>= 1;
            }
            self.holding_zero = !self.holding_one;
        }
        if flags & HYBRID_FLAG != 0 && chan == 0 {
            self.update_error_limit(flags);
        }
        let c = &mut self.c[chan];
        let (mut low, mut high);
        if ones == 0 {
            low = 0u32;
            high = get_med(c, 0).wrapping_sub(1);
            dec_med(c, 0);
        } else {
            low = get_med(c, 0);
            inc_med(c, 0);
            if ones == 1 {
                high = low.wrapping_add(get_med(c, 1)).wrapping_sub(1);
                dec_med(c, 1);
            } else {
                low = low.wrapping_add(get_med(c, 1));
                inc_med(c, 1);
                if ones == 2 {
                    high = low.wrapping_add(get_med(c, 2)).wrapping_sub(1);
                    dec_med(c, 2);
                } else {
                    low = low.wrapping_add((ones - 2).wrapping_mul(get_med(c, 2)));
                    high = low.wrapping_add(get_med(c, 2)).wrapping_sub(1);
                    inc_med(c, 2);
                }
            }
        }
        low &= 0x7fff_ffff;
        high &= 0x7fff_ffff;
        if low > high {
            high = low;
        }
        let mut mid = (high + low + 1) >> 1;
        if c.error_limit == 0 {
            mid = bs.code(high - low) + low;
        } else {
            while high - low > c.error_limit {
                if bs.bit() != 0 {
                    low = mid;
                } else {
                    high = mid - 1;
                }
                mid = (high + low + 1) >> 1;
            }
        }
        let sign = bs.bit() != 0;
        if flags & HYBRID_BITRATE != 0 {
            c.slow_level = c
                .slow_level
                .wrapping_sub(c.slow_level.wrapping_add(SLO) >> SLS);
            c.slow_level = c.slow_level.wrapping_add(wp_log2(mid) as u32);
        }
        Some(if sign { !(mid as i32) } else { mid as i32 })
    }
}

// ---- decorrelation ----

#[derive(Default, Clone, Copy)]
struct Pass {
    term: i32,
    delta: i32,
    weight_a: i32,
    weight_b: i32,
    a: [i32; MAX_TERM],
    b: [i32; MAX_TERM],
}

fn apply_weight(weight: i32, sample: i32) -> i32 {
    if sample == i32::from(sample as i16) {
        weight.wrapping_mul(sample).wrapping_add(512) >> 10
    } else {
        (((sample & 0xffff).wrapping_mul(weight) >> 9)
            .wrapping_add(((sample & !0xffff) >> 9).wrapping_mul(weight))
            .wrapping_add(1))
            >> 1
    }
}

fn update_weight(weight: &mut i32, delta: i32, source: i32, result: i32) {
    if source != 0 && result != 0 {
        let s = (source ^ result) >> 31;
        *weight = (delta ^ s).wrapping_add(weight.wrapping_sub(s));
    }
}

fn update_weight_clip(weight: &mut i32, delta: i32, source: i32, result: i32) {
    if source != 0 && result != 0 {
        let s = (source ^ result) >> 31;
        let mut w = (*weight ^ s).wrapping_add(delta.wrapping_sub(s));
        if w > 1024 {
            w = 1024;
        }
        *weight = (w ^ s).wrapping_sub(s);
    }
}

fn decorr_mono(p: &mut Pass, buf: &mut [i32]) {
    let delta = p.delta;
    let mut w = p.weight_a;
    match p.term {
        17 | 18 => {
            for x in buf.iter_mut() {
                let sam = if p.term == 17 {
                    p.a[0].wrapping_mul(2).wrapping_sub(p.a[1])
                } else {
                    p.a[0].wrapping_mul(3).wrapping_sub(p.a[1]) >> 1
                };
                p.a[1] = p.a[0];
                p.a[0] = apply_weight(w, sam).wrapping_add(*x);
                update_weight(&mut w, delta, sam, *x);
                *x = p.a[0];
            }
        }
        t => {
            let mut m = 0usize;
            let mut k = (t as usize) & (MAX_TERM - 1);
            for x in buf.iter_mut() {
                let sam = p.a[m];
                p.a[k] = apply_weight(w, sam).wrapping_add(*x);
                update_weight(&mut w, delta, sam, *x);
                *x = p.a[k];
                m = (m + 1) & (MAX_TERM - 1);
                k = (k + 1) & (MAX_TERM - 1);
            }
        }
    }
    p.weight_a = w;
}

fn decorr_stereo(p: &mut Pass, buf: &mut [i32]) {
    let delta = p.delta;
    match p.term {
        17 | 18 => {
            for f in buf.chunks_exact_mut(2) {
                let sam = if p.term == 17 {
                    p.a[0].wrapping_mul(2).wrapping_sub(p.a[1])
                } else {
                    p.a[0].wrapping_add(p.a[0].wrapping_sub(p.a[1]) >> 1)
                };
                p.a[1] = p.a[0];
                let tmp = f[0];
                p.a[0] = apply_weight(p.weight_a, sam).wrapping_add(tmp);
                f[0] = p.a[0];
                update_weight(&mut p.weight_a, delta, sam, tmp);
                let sam = if p.term == 17 {
                    p.b[0].wrapping_mul(2).wrapping_sub(p.b[1])
                } else {
                    p.b[0].wrapping_add(p.b[0].wrapping_sub(p.b[1]) >> 1)
                };
                p.b[1] = p.b[0];
                let tmp = f[1];
                p.b[0] = apply_weight(p.weight_b, sam).wrapping_add(tmp);
                f[1] = p.b[0];
                update_weight(&mut p.weight_b, delta, sam, tmp);
            }
        }
        -1 => {
            for f in buf.chunks_exact_mut(2) {
                let sam = f[0].wrapping_add(apply_weight(p.weight_a, p.a[0]));
                update_weight_clip(&mut p.weight_a, delta, p.a[0], f[0]);
                f[0] = sam;
                p.a[0] = f[1].wrapping_add(apply_weight(p.weight_b, sam));
                update_weight_clip(&mut p.weight_b, delta, sam, f[1]);
                f[1] = p.a[0];
            }
        }
        -2 => {
            for f in buf.chunks_exact_mut(2) {
                let sam = f[1].wrapping_add(apply_weight(p.weight_b, p.b[0]));
                update_weight_clip(&mut p.weight_b, delta, p.b[0], f[1]);
                f[1] = sam;
                p.b[0] = f[0].wrapping_add(apply_weight(p.weight_a, sam));
                update_weight_clip(&mut p.weight_a, delta, sam, f[0]);
                f[0] = p.b[0];
            }
        }
        -3 => {
            for f in buf.chunks_exact_mut(2) {
                let sam_a = f[0].wrapping_add(apply_weight(p.weight_a, p.a[0]));
                update_weight_clip(&mut p.weight_a, delta, p.a[0], f[0]);
                let sam_b = f[1].wrapping_add(apply_weight(p.weight_b, p.b[0]));
                update_weight_clip(&mut p.weight_b, delta, p.b[0], f[1]);
                f[0] = sam_a;
                p.b[0] = sam_a;
                f[1] = sam_b;
                p.a[0] = sam_b;
            }
        }
        t => {
            let mut m = 0usize;
            let mut k = (t as usize) & (MAX_TERM - 1);
            for f in buf.chunks_exact_mut(2) {
                let sam = p.a[m];
                p.a[k] = apply_weight(p.weight_a, sam).wrapping_add(f[0]);
                update_weight(&mut p.weight_a, delta, sam, f[0]);
                f[0] = p.a[k];
                let sam = p.b[m];
                p.b[k] = apply_weight(p.weight_b, sam).wrapping_add(f[1]);
                update_weight(&mut p.weight_b, delta, sam, f[1]);
                f[1] = p.b[k];
                m = (m + 1) & (MAX_TERM - 1);
                k = (k + 1) & (MAX_TERM - 1);
            }
        }
    }
}

// ---- blocks ----

#[derive(Clone, Copy)]
struct Header {
    size: usize,
    version: u16,
    block_samples: u32,
    flags: u32,
    crc: u32,
}

fn parse_header(d: &[u8]) -> Option<Header> {
    if d.len() < 32 || &d[..4] != b"wvpk" {
        return None;
    }
    let u32le = |o: usize| u32::from_le_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]]);
    Some(Header {
        size: u32le(4) as usize,
        version: u16::from_le_bytes([d[8], d[9]]),
        block_samples: u32le(20),
        flags: u32le(24),
        crc: u32le(28),
    })
}

struct Meta<'a> {
    id: u8,
    data: &'a [u8],
}

fn metadata(mut body: &[u8]) -> Result<Vec<Meta<'_>>> {
    let mut out = Vec::new();
    while body.len() >= 2 {
        let mut id = body[0];
        let mut len = usize::from(body[1]) << 1;
        let mut at = 2;
        if id & 0x80 != 0 {
            id &= !0x80;
            let ext = body
                .get(2..4)
                .ok_or_else(|| Error::truncated("WavPack metadata ends early"))?;
            len += (usize::from(ext[0]) << 9) + (usize::from(ext[1]) << 17);
            at = 4;
        }
        if id & 0x40 != 0 {
            if len == 0 {
                return Err(bad("WavPack: odd-sized metadata with no data"));
            }
            id &= !0x40;
            len -= 1;
        }
        let padded = len + (len & 1);
        if body.len() < at + padded {
            return Err(Error::truncated("WavPack metadata ends early"));
        }
        out.push(Meta {
            id,
            data: &body[at..at + len],
        });
        body = &body[at + padded..];
    }
    Ok(out)
}

/// Format facts that the blocks announce.
#[derive(Default)]
struct Format {
    channels: usize,
    mask: u32,
    rate: u32,
}

struct Decoded {
    /// `frames * channels` samples, interleaved, at the stored width.
    samples: Vec<i32>,
    channels: usize,
}

type Wvx<'a> = (&'a [u8], u32, bool);

fn parse_channel_info(d: &[u8], fmt: &mut Format) -> Result<()> {
    if fmt.channels != 0 {
        return Ok(());
    }
    if d.is_empty() || d.len() > 7 {
        return Err(bad("WavPack: bad channel info"));
    }
    let mut mask = 0u32;
    if d.len() >= 6 {
        fmt.channels = (usize::from(d[0]) | (usize::from(d[2] & 0xf) << 8)) + 1;
        mask = u32::from(d[3]) | (u32::from(d[4]) << 8) | (u32::from(d[5]) << 16);
        if d.len() == 7 {
            mask |= u32::from(d[6]) << 24;
        }
    } else {
        fmt.channels = usize::from(d[0]);
        for (i, &b) in d[1..].iter().enumerate() {
            mask |= u32::from(b) << (8 * i);
        }
    }
    fmt.mask = mask;
    Ok(())
}

fn decode_block(h: &Header, body: &[u8], fmt: &mut Format) -> Result<Decoded> {
    let flags = h.flags;
    if !(0x402..=0x410).contains(&h.version) {
        return Err(bad("WavPack: unsupported stream version"));
    }
    if flags & DSD_FLAG != 0 {
        return Err(Error::new(
            ErrorCode::UnsupportedFormat,
            "WavPack DSD audio is not supported",
        ));
    }
    if flags & FLOAT_DATA != 0 {
        return Err(Error::new(
            ErrorCode::UnsupportedFormat,
            "WavPack floating-point audio is not supported",
        ));
    }
    if flags & MONO_DATA == MONO_DATA {
        return Err(bad("WavPack: block is both mono and false stereo"));
    }
    if flags & HYBRID_FLAG != 0 && h.version == 0x402 {
        return Err(Error::new(
            ErrorCode::UnsupportedFormat,
            "WavPack 4.0 hybrid files are not supported",
        ));
    }
    let mono = flags & MONO_DATA != 0;
    let n = h.block_samples as usize;
    let mut passes: Vec<Pass> = Vec::new();
    let mut words = Words::default();
    let mut wv: Option<&[u8]> = None;
    let mut wvx: Option<Wvx> = None;
    let mut int32 = [0u32; 4];
    for m in metadata(body)? {
        match m.id {
            ID_DECORR_TERMS => {
                if m.data.len() > 16 {
                    return Err(bad("WavPack: too many decorrelation terms"));
                }
                let count = m.data.len();
                passes = vec![Pass::default(); count];
                for (i, &b) in m.data.iter().enumerate() {
                    let p = &mut passes[count - 1 - i];
                    p.term = i32::from(b & 0x1f) - 5;
                    p.delta = i32::from((b >> 5) & 7);
                    let t = p.term;
                    if t == 0
                        || t < -3
                        || (t > MAX_TERM as i32 && t < 17)
                        || t > 18
                        || (mono && t < 0)
                    {
                        return Err(bad("WavPack: invalid decorrelation term"));
                    }
                }
            }
            ID_DECORR_WEIGHTS => {
                let per = if mono { 1 } else { 2 };
                let mut terms = m.data.len() / per;
                if terms > passes.len() {
                    return Err(bad("WavPack: too many decorrelation weights"));
                }
                let mut at = 0;
                for p in passes.iter_mut().rev() {
                    if terms == 0 {
                        break;
                    }
                    terms -= 1;
                    p.weight_a = restore_weight(m.data[at] as i8);
                    at += 1;
                    if !mono {
                        p.weight_b = restore_weight(m.data[at] as i8);
                        at += 1;
                    }
                }
            }
            ID_DECORR_SAMPLES => {
                let d = m.data;
                let mut at = 0usize;
                let s16 = |at: usize| -> Result<i32> {
                    let b = d
                        .get(at..at + 2)
                        .ok_or_else(|| bad("WavPack: decorrelation samples are short"))?;
                    Ok(wp_exp2s(i32::from(i16::from_le_bytes([b[0], b[1]]))))
                };
                for p in passes.iter_mut().rev() {
                    if at >= d.len() {
                        break;
                    }
                    if p.term > MAX_TERM as i32 {
                        p.a[0] = s16(at)?;
                        p.a[1] = s16(at + 2)?;
                        at += 4;
                        if !mono {
                            p.b[0] = s16(at)?;
                            p.b[1] = s16(at + 2)?;
                            at += 4;
                        }
                    } else if p.term < 0 {
                        p.a[0] = s16(at)?;
                        p.b[0] = s16(at + 2)?;
                        at += 4;
                    } else {
                        for k in 0..p.term as usize {
                            p.a[k] = s16(at)?;
                            at += 2;
                            if !mono {
                                p.b[k] = s16(at)?;
                                at += 2;
                            }
                        }
                    }
                }
                if at != d.len() {
                    return Err(bad("WavPack: decorrelation samples have the wrong length"));
                }
            }
            ID_ENTROPY_VARS => {
                if m.data.len() != if mono { 6 } else { 12 } {
                    return Err(bad("WavPack: entropy variables have the wrong length"));
                }
                let v = |i: usize| {
                    wp_exp2s(i32::from(m.data[i]) + (i32::from(m.data[i + 1]) << 8)) as u32
                };
                words.c[0].median = [v(0), v(2), v(4)];
                if !mono {
                    words.c[1].median = [v(6), v(8), v(10)];
                }
            }
            ID_HYBRID_PROFILE => {
                let d = m.data;
                let chans = if mono { 1 } else { 2 };
                let mut at = 0usize;
                let u16at = |at: usize| -> Result<i32> {
                    let b = d
                        .get(at..at + 2)
                        .ok_or_else(|| bad("WavPack: hybrid profile is short"))?;
                    Ok(i32::from(b[0]) + (i32::from(b[1]) << 8))
                };
                if flags & HYBRID_BITRATE != 0 {
                    for ch in 0..chans {
                        words.c[ch].slow_level = wp_exp2s(u16at(at)?) as u32;
                        at += 2;
                    }
                }
                for ch in 0..chans {
                    words.bitrate_acc[ch] = (u16at(at)? as u32) << 16;
                    at += 2;
                }
                if at < d.len() {
                    for ch in 0..chans {
                        words.bitrate_delta[ch] = wp_exp2s(i32::from(u16at(at)? as i16)) as u32;
                        at += 2;
                    }
                    if at < d.len() {
                        return Err(bad("WavPack: hybrid profile has trailing data"));
                    }
                }
            }
            ID_FLOAT_INFO => {}
            ID_INT32_INFO => {
                if m.data.len() != 4 {
                    return Err(bad("WavPack: bad extended-integer info"));
                }
                for (dst, &s) in int32.iter_mut().zip(m.data) {
                    *dst = u32::from(s);
                }
            }
            ID_CHANNEL_INFO => parse_channel_info(m.data, fmt)?,
            ID_SAMPLE_RATE => {
                if m.data.len() == 3 || m.data.len() == 4 {
                    let mut r = u32::from(m.data[0])
                        | (u32::from(m.data[1]) << 8)
                        | (u32::from(m.data[2]) << 16);
                    if m.data.len() == 4 {
                        r |= u32::from(m.data[3] & 0x7f) << 24;
                    }
                    fmt.rate = r;
                }
            }
            ID_WV_BITSTREAM => {
                if m.data.is_empty() || m.data.len() & 1 != 0 {
                    return Err(bad("WavPack: bad audio bitstream"));
                }
                wv = Some(m.data);
            }
            ID_WVX_BITSTREAM | ID_WVX_NEW_BITSTREAM => {
                if m.data.len() <= 4 || m.data.len() & 1 != 0 {
                    return Err(bad("WavPack: bad extension bitstream"));
                }
                let crc = u32::from_le_bytes([m.data[0], m.data[1], m.data[2], m.data[3]]);
                wvx = Some((&m.data[4..], crc, m.id == ID_WVX_NEW_BITSTREAM));
            }
            ID_DSD_BLOCK => {
                return Err(Error::new(
                    ErrorCode::UnsupportedFormat,
                    "WavPack DSD audio is not supported",
                ));
            }
            id if id & 0x20 != 0 || id == 0 => {}
            _ => return Err(bad("WavPack: unknown required metadata")),
        }
    }
    if fmt.rate == 0 {
        let idx = ((flags & SRATE_MASK) >> SRATE_LSB) as usize;
        fmt.rate = RATES.get(idx).copied().unwrap_or(0);
    }
    let wv = wv.ok_or_else(|| bad("WavPack: block has no audio bitstream"))?;

    let chans = if mono { 1 } else { 2 };
    let mag = (flags & MAG_MASK) >> MAG_LSB;
    let mut mute_limit = (1i64 << mag) + 2;
    if flags & HYBRID_FLAG != 0 {
        mute_limit = mute_limit * 3 + 128;
    }
    let mut buf = vec![0i32; n * chans];
    let mut bs = Bits::new(wv);
    for (i, slot) in buf.iter_mut().enumerate() {
        let ch = if mono { 0 } else { i & 1 };
        let v = words.get_word(&mut bs, ch, flags);
        if bs.eof {
            return Err(Error::truncated("WavPack audio bitstream ends early"));
        }
        *slot = v.ok_or_else(|| bad("WavPack: audio bitstream is damaged"))?;
    }
    for p in &mut passes {
        if mono {
            decorr_mono(p, &mut buf);
        } else {
            decorr_stereo(p, &mut buf);
        }
    }
    let mut crc = 0xffff_ffffu32;
    if mono {
        for &x in &buf {
            if i64::from(x).abs() > mute_limit {
                return Err(bad("WavPack: sample out of range (damaged block)"));
            }
            crc = crc.wrapping_mul(3).wrapping_add(x as u32);
        }
    } else {
        for f in buf.chunks_exact_mut(2) {
            if flags & JOINT_STEREO != 0 {
                f[1] = f[1].wrapping_sub(f[0] >> 1);
                f[0] = f[0].wrapping_add(f[1]);
            }
            if i64::from(f[0]).abs() > mute_limit || i64::from(f[1]).abs() > mute_limit {
                return Err(bad("WavPack: sample out of range (damaged block)"));
            }
            crc = crc
                .wrapping_add(crc << 3)
                .wrapping_add((f[0] as u32) << 1)
                .wrapping_add(f[0] as u32)
                .wrapping_add(f[1] as u32);
        }
    }
    if crc != h.crc {
        return Err(bad("WavPack: block checksum does not match"));
    }
    fixup(&mut buf, flags, int32, wvx)?;
    if flags & FALSE_STEREO != 0 {
        let mut out = Vec::with_capacity(buf.len() * 2);
        for &x in &buf {
            out.push(x);
            out.push(x);
        }
        return Ok(Decoded {
            samples: out,
            channels: 2,
        });
    }
    Ok(Decoded {
        samples: buf,
        channels: chans,
    })
}

/// Undo the factoring of one extended sample (zeros, ones or duplicated low bits).
fn unfactor(x: i32, zeros: u32, ones: u32, dups: u32) -> i32 {
    let u = x as u32;
    if zeros != 0 {
        (u << zeros) as i32
    } else if ones != 0 {
        (u.wrapping_add(1) << ones).wrapping_sub(1) as i32
    } else if dups != 0 {
        let lsb = u & 1;
        (u.wrapping_add(lsb) << dups).wrapping_sub(lsb) as i32
    } else {
        x
    }
}

/// The final operations of a block: restore bits that were moved to the extension stream or
/// factored out, clip hybrid output to its range, and apply the left shift.
fn fixup(buf: &mut [i32], flags: u32, int32: [u32; 4], wvx: Option<Wvx>) -> Result<()> {
    let lossy = flags & HYBRID_FLAG != 0;
    let mut shift = (flags & SHIFT_MASK) >> SHIFT_LSB;
    if flags & INT32_DATA != 0 {
        let sent_bits = int32[0] & 0x1f;
        let mut zeros = int32[1] & 0x1f;
        let mut ones = int32[2] & 0x1f;
        let mut dups = int32[3] & 0x1f;
        if let Some((data, crc_x, new_format)) = wvx {
            let mut bs = Bits::new(data);
            let max_width = if new_format { bs.bits(5) } else { 0 };
            let mut crc = 0xffff_ffffu32;
            for x in buf.iter_mut() {
                if sent_bits != 0 {
                    if max_width != 0 {
                        let pvalue = if *x < 0 { !*x } else { *x } as u32;
                        let width = nbits(pvalue) + sent_bits;
                        let mut to_read = sent_bits as i32;
                        let read = if width <= max_width {
                            true
                        } else {
                            to_read -= (width - max_width) as i32;
                            to_read > 0
                        };
                        if read {
                            let d = bs.bits(to_read as u32);
                            let d = d & ((1u64 << to_read) - 1) as u32;
                            *x = ((((*x as u32) << to_read) | d) << (sent_bits as i32 - to_read))
                                as i32;
                        } else {
                            *x = ((*x as u32) << sent_bits) as i32;
                        }
                    } else {
                        let d = bs.bits(sent_bits) & ((1u64 << sent_bits) - 1) as u32;
                        *x = (((*x as u32) << sent_bits) | d) as i32;
                    }
                }
                *x = unfactor(*x, zeros, ones, dups);
                let u = *x as u32;
                crc = crc
                    .wrapping_mul(9)
                    .wrapping_add((u & 0xffff).wrapping_mul(3))
                    .wrapping_add((u >> 16) & 0xffff);
            }
            if bs.eof {
                return Err(Error::truncated("WavPack extension bitstream ends early"));
            }
            if crc != crc_x {
                return Err(bad("WavPack: extension checksum does not match"));
            }
        } else if sent_bits == 0 && zeros + ones + dups != 0 {
            while lossy && flags & BYTES_STORED == 3 && shift < 8 {
                if zeros != 0 {
                    zeros -= 1;
                } else if ones != 0 {
                    ones -= 1;
                } else if dups != 0 {
                    dups -= 1;
                } else {
                    break;
                }
                shift += 1;
            }
            for x in buf.iter_mut() {
                *x = unfactor(*x, zeros, ones, dups);
            }
        } else {
            shift += zeros + sent_bits + ones + dups;
        }
    }
    shift &= 0x1f;
    if lossy {
        let (min_v, max_v): (i32, i32) = match flags & BYTES_STORED {
            0 => (-128 >> shift, 127 >> shift),
            1 => (-32768 >> shift, 32767 >> shift),
            2 => (-8_388_608 >> shift, 8_388_607 >> shift),
            _ => (i32::MIN >> shift, i32::MAX >> shift),
        };
        for x in buf.iter_mut() {
            let v = (*x).clamp(min_v, max_v);
            *x = ((v as u32) << shift) as i32;
        }
    } else if shift != 0 {
        for x in buf.iter_mut() {
            *x = ((*x as u32) << shift) as i32;
        }
    }
    Ok(())
}

/// Join the blocks of one multichannel sequence into interleaved frames.
fn flush(seq: &mut Vec<Decoded>, out: &mut Vec<i32>, channels: &mut usize) -> Result<()> {
    if seq.is_empty() {
        return Ok(());
    }
    let ch: usize = seq.iter().map(|d| d.channels).sum();
    let frames = seq[0].samples.len() / seq[0].channels;
    if seq.iter().any(|d| d.samples.len() / d.channels != frames) {
        return Err(bad("WavPack: blocks of one sequence differ in length"));
    }
    if *channels == 0 {
        *channels = ch;
    } else if *channels != ch {
        return Err(bad("WavPack: channel count changes inside the file"));
    }
    let start = out.len();
    out.resize(start + frames * ch, 0);
    let mut offset = 0;
    for d in seq.iter() {
        for f in 0..frames {
            for c in 0..d.channels {
                out[start + f * ch + offset + c] = d.samples[f * d.channels + c];
            }
        }
        offset += d.channels;
    }
    seq.clear();
    Ok(())
}

/// Decode a WavPack file.
pub fn read(data: &[u8], limits: &Limits) -> Result<(Audio, Notes)> {
    let mut notes = Notes::new();
    let mut fmt = Format::default();
    let mut bits = 0u8;
    let mut out: Vec<i32> = Vec::new();
    let mut channels = 0usize;
    let mut pos = 0usize;
    let mut seq: Vec<Decoded> = Vec::new();
    while pos + 32 <= data.len() {
        let Some(h) = parse_header(&data[pos..]) else {
            break;
        };
        let end = pos
            .checked_add(8)
            .and_then(|p| p.checked_add(h.size))
            .filter(|&e| e <= data.len() && e >= pos + 32)
            .ok_or_else(|| Error::truncated("WavPack block is truncated"))?;
        let body = &data[pos + 32..end];
        pos = end;
        if h.block_samples == 0 {
            // A metadata-only block can still announce the channel layout.
            if let Ok(list) = metadata(body) {
                for m in list {
                    if m.id == ID_CHANNEL_INFO {
                        let _ = parse_channel_info(m.data, &mut fmt);
                    }
                }
            }
            continue;
        }
        if bits == 0 {
            let bytes = (h.flags & BYTES_STORED) + 1;
            bits = (bytes * 8 - ((h.flags & SHIFT_MASK) >> SHIFT_LSB)).clamp(1, 32) as u8;
        }
        if !seq.is_empty() && h.flags & INITIAL_BLOCK != 0 {
            flush(&mut seq, &mut out, &mut channels)?;
        }
        check_samples(
            (out.len() as u64).saturating_add(u64::from(h.block_samples) * 2),
            limits,
        )?;
        seq.push(decode_block(&h, body, &mut fmt)?);
        if h.flags & FINAL_BLOCK != 0 {
            flush(&mut seq, &mut out, &mut channels)?;
        }
    }
    flush(&mut seq, &mut out, &mut channels)?;
    if channels == 0 || out.is_empty() {
        return Err(Error::corrupt("WavPack file has no audio"));
    }
    if fmt.channels != 0 && fmt.channels != channels {
        notes.push(Note::new(
            Severity::Warning,
            "wavpack.channels",
            "the channel count in the header differs from the blocks; the blocks were used",
        ));
    }
    if fmt.rate == 0 {
        return Err(Error::corrupt("WavPack file has no usable sample rate"));
    }
    let channels16 = u16::try_from(channels).map_err(|_| bad("WavPack: too many channels"))?;
    let mut a = Audio::new(fmt.rate, channels16, Samples::Int { bits, data: out });
    if fmt.mask != 0 && fmt.mask.count_ones() as usize == channels {
        a.channel_mask = fmt.mask;
    }
    ape::parse(data, &mut a.tags, &mut a.pictures);
    Ok((a, notes))
}
